# A Scrap without enough stock stays draft; the others are validated.
failed = []
for scrap in records.filtered(lambda s: s.state == "draft"):
    if isinstance(scrap.action_validate(), dict):
        failed.append(scrap.origin or scrap.name)
if failed:
    action = {
        "type": "ir.actions.client",
        "tag": "display_notification",
        "params": {
            "title": "Validate",
            "message": "Not enough stock, still draft: %s" % ", ".join(failed),
            "type": "warning",
            "sticky": True,
        },
    }
